    public void loadSmsCount() {
        long[] sentSms = getSentSms();
        int sentSmsCount = 0;
        long period = 0;
        if (sentSms.length >= 1) {
            for (int i = sentSms.length - 1; i >= 0; i--) {
                if (i == sentSms.length - 1) {
                    period += System.currentTimeMillis() - sentSms[i];
                } else {
                    period += sentSms[i + 1] - sentSms[i];
                }
                if (period > days * Settings.DAY) {
                    break;
                }
                sentSmsCount++;
            }
        }
        int smsCount = maxSms - sentSmsCount;
        if (sms.size() > smsCount) {
            maxSendCount = smsCount;
        } else {
            maxSendCount = sms.size();
        }
    }

